sys_script.script:
(function executeRule(current, previous) {
    var type = current.getValue('type');
    var extent = current.getValue('extent');

    if (type === 'deletion') {
        if (gs.nil(extent)) {
            gs.addErrorMessage('Deletion sync filters must have at least one Extent value selected. Choose "Managed" and/or "Unmanaged".');
            current.extent.setError('At least one extent is required for deletion filters.');
            current.setAbortAction(true);
            return;
        }

        var extentValues = extent.split(',');
        for (var i = 0; i < extentValues.length; i++) {
            if (extentValues[i] === 'unknown') {
                gs.addErrorMessage('Deletion sync filters cannot include "Unknown" in the Extent field. Only "Managed" and "Unmanaged" workloads can be targeted for deletion.');
                current.extent.setError('Remove "Unknown" from the extent.');
                current.setAbortAction(true);
                return;
            }
        }
    }
})(current, previous);
